// Get incoming visitors from webhook
const incomingVisitors = $input.all()[0].json.body;

// Get existing visitors from Google Sheets
const existingVisitors = $input.all()[1].json.data || [];

// Create a set of existing profile IDs and emails for fast lookup
const existingIds = new Set(existingVisitors.map(v => v.profileId));
const existingEmails = new Set(existingVisitors.map(v => v.email).filter(e => e));

// Filter out duplicates
const newVisitors = incomingVisitors.filter(visitor => {
  // Check if profile ID already exists
  if (existingIds.has(visitor.profileId)) {
    return false;
  }
  // Check if email already exists (if email is provided)
  if (visitor.email && existingEmails.has(visitor.email)) {
    return false;
  }
  return true;
});

// Add timestamp to new visitors
const visitorsWithTimestamp = newVisitors.map(v => ({
  ...v,
  timestamp: new Date().toISOString()
}));

// Return deduped visitors
return [{
  json: {
    newVisitors: visitorsWithTimestamp,
    newVisitorsCount: visitorsWithTimestamp.length,
    totalIncomingCount: incomingVisitors.length,
    duplicatesFound: incomingVisitors.length - visitorsWithTimestamp.length
  }
}];

// Combine original visitor data with Explorium enrichment results
const originalVisitor = $input.all()[0].json;
const enrichmentData = $input.all()[1].json || {};

const enrichedVisitor = {
  // Original fields
  profileId: originalVisitor.profileId,
  name: originalVisitor.name,
  headline: originalVisitor.headline,
  company: originalVisitor.company,
  email: originalVisitor.email,
  linkedinUrl: originalVisitor.linkedinUrl,
  timestamp: originalVisitor.timestamp,

  // Enriched fields from Explorium
  phone: enrichmentData.phone || '',
  address: enrichmentData.address || '',
  industry: enrichmentData.industry || '',
  companySize: enrichmentData.companySize || '',
  revenue: enrichmentData.revenue || '',
  yearsAtCompany: enrichmentData.yearsAtCompany || '',
  linkedinConnections: enrichmentData.linkedinConnections || '',
  skills: enrichmentData.skills ? enrichmentData.skills.join(', ') : '',
  workHistory: enrichmentData.workHistory ? enrichmentData.workHistory.map(w => `${w.title} at ${w.company}`).join(' | ') : '',

  // Metadata
  dataSource: 'LinkedIn Company Visitors + Explorium Enrichment',
  enrichedAt: new Date().toISOString()
};

return [{
  json: enrichedVisitor
}];
